const ruleNamesByTarget = `-- name: RuleNamesByTarget :many
SELECT DISTINCT rule_name FROM eventbridge_targets
WHERE partition=? AND account=? AND region=? AND bus_name=? AND arn=? ORDER BY rule_name
`

type RuleNamesByTargetParams struct {
	Partition string
	Account   string
	Region    string
	BusName   string
	Arn       string
}

func (q *Queries) RuleNamesByTarget(ctx context.Context, arg RuleNamesByTargetParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, ruleNamesByTarget,
		arg.Partition,
		arg.Account,
		arg.Region,
		arg.BusName,
		arg.Arn,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var rule_name string
		if err := rows.Scan(&rule_name); err != nil {
			return nil, err
		}
		items = append(items, rule_name)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

